import sys; sys.path.insert(0, '/root/cert_manip_resist_eval')
import itertools, numpy as np, statsmodels.api as sm, json
from pathlib import Path
from src.unified_data_loader import (
    DATASETS, ATTACKS, SCORES_DIR, CKPT_FILES,
    load_pairs, load_mi_data, _is_valid_score
)

EPS = 1e-6

mi_data = load_mi_data()
MI_MODELS = mi_data['models']
print('Using MI models:', MI_MODELS)

# Load scores using MI model names
def load_scores_mi():
    clean = {ds: {} for ds in DATASETS}
    attacked = {ds: {a: {} for a in ATTACKS} for ds in DATASETS}

    def _invert(scores):
        swap = {'A': 'B', 'B': 'A', 'tie': 'tie'}
        return [{**s, 'winner': swap.get(s.get('winner', 'tie'), 'tie')} for s in scores]

    # Load from checkpoints (use MI model names)
    for ckpt_path in CKPT_FILES:
        if not Path(ckpt_path).exists(): continue
        with open(ckpt_path) as f:
            data = json.load(f)
        for ds in DATASETS:
            for mid, scores in data.get('clean_scores', {}).get(ds, {}).items():
                if mid in MI_MODELS and mid not in clean[ds]:
                    clean[ds][mid] = scores
            for atk in ATTACKS:
                for mid, scores in data.get('attacked_scores', {}).get(ds, {}).get(atk, {}).items():
                    if mid in MI_MODELS and mid not in attacked[ds][atk]:
                        if atk == 'position_bias':
                            scores = _invert(scores)
                        attacked[ds][atk][mid] = scores

    # Load from individual score files
    scores_dir = Path(SCORES_DIR)
    if scores_dir.exists():
        for mid in MI_MODELS:
            for ds in DATASETS:
                fp = scores_dir / f'{mid}__{ds}__clean.json'
                if fp.exists() and mid not in clean[ds]:
                    with open(fp) as f:
                        clean[ds][mid] = json.load(f).get('scores', [])
                for atk in ATTACKS:
                    fp = scores_dir / f'{mid}__{ds}__{atk}.json'
                    if fp.exists() and mid not in attacked[ds][atk]:
                        with open(fp) as f:
                            scores = json.load(f).get('scores', [])
                            if atk == 'position_bias':
                                scores = _invert(scores)
                            attacked[ds][atk][mid] = scores
    return clean, attacked

clean, attacked = load_scores_mi()
pairs = load_pairs()

# Check coverage
for ds in DATASETS:
    models_with = [m for m in MI_MODELS if m in clean[ds]]
    print(f'{ds}: {len(models_with)}/15 models with clean data')

# K=5 mmlu×prompt_injection
def majority_vote(votes):
    counts = {'A': 0, 'B': 0, 'tie': 0}
    for v in votes: counts[v] = counts.get(v, 0) + 1
    mc = max(counts.values())
    winners = [k for k, c in counts.items() if c == mc]
    if len(winners) == 1: return winners[0]
    for w in winners:
        if w != 'tie': return w
    return 'tie'

def panel_asr(jids, cd, ad, pd):
    n = min(len(pd), *(len(cd[j]) for j in jids), *(len(ad[j]) for j in jids))
    nf=nc=0
    for i in range(n):
        if not all(_is_valid_score(cd[j][i]) for j in jids): continue
        if not all(_is_valid_score(ad[j][i]) for j in jids): continue
        gt = pd[i]['ground_truth_winner']
        cv = majority_vote([cd[j][i]['winner'] for j in jids])
        if cv != gt: continue
        nc += 1
        av = majority_vote([ad[j][i]['winner'] for j in jids])
        if av != gt: nf += 1
    return nf / max(nc, 1)

def indiv_asr(cl, at, p):
    n = min(len(cl), len(at), len(p))
    nf=nc=0
    for i in range(n):
        if not _is_valid_score(cl[i]) or not _is_valid_score(at[i]): continue
        gt = p[i]['ground_truth_winner']
        if cl[i]['winner'] == gt:
            nc += 1
            if at[i]['winner'] != gt: nf += 1
    return nf / max(nc, 1)

def keff(mi, idx):
    K=len(idx); ke=0
    for i in idx:
        t=1
        for j in idx:
            if i!=j: t+=np.exp(-2*mi[i,j])
        ke+=t
    return ke/K

ds,atk = 'mmlu','prompt_injection'
mi_mat = np.array(mi_data['mi_matrix'][ds])
combos = list(itertools.combinations(range(len(MI_MODELS)), 5))

ia = {}
for mid in MI_MODELS:
    if mid in clean[ds] and mid in attacked[ds][atk]:
        ia[mid] = indiv_asr(clean[ds][mid], attacked[ds][atk][mid], pairs[ds])

ks,es,ass_=[],[],[]
for c in combos:
    jids = [MI_MODELS[i] for i in c]
    if not all(m in clean[ds] and m in attacked[ds][atk] for m in jids): continue
    ks.append(keff(mi_mat,list(c)))
    es.append(max(ia.get(m,0) for m in jids))
    ass_.append(panel_asr(jids,clean[ds],attacked[ds][atk],pairs[ds]))

ks,es,ass_=np.array(ks),np.array(es),np.array(ass_)
print(f'\\nK=5 mmlu×pi: {len(ks)} panels')
print(f'ASR: mean={ass_.mean():.4f} (expected 0.1751)')
print(f'Keff: mean={ks.mean():.4f} (expected 3.5510)')

y = np.log(ass_ + EPS)
X = sm.add_constant(np.column_stack([np.log(ks), np.log(es + EPS)]))
fit = sm.OLS(y, X).fit()
print(f'OLS R²={fit.rsquared:.4f} (expected 0.6038)')
